const state = { token: localStorage.getItem('minehive.token') ?? '', bots: [], goals: [], admins: [], health: null, ai: null, settings: null, autonomyObjectives: [], editorBotId: null, memoryBrowser: { offset: 0, limit: 50, loading: false, data: null }, recovery: { loading: false, data: null, timer: null }, polling: { timer: null, running: false, failures: 0 } };
const $ = selector => document.querySelector(selector);
const $$ = selector => [...document.querySelectorAll(selector)];
$('#apiToken').value = state.token;

async function api(path, options = {}) {
  const headers = { ...(options.body ? { 'content-type': 'application/json' } : {}), ...(state.token ? { authorization: `Bearer ${state.token}` } : {}), ...options.headers };
  const response = await fetch(path, { ...options, headers, signal: options.signal ?? AbortSignal.timeout(15_000) }); const payload = await response.json().catch(() => ({}));
  if (!response.ok) { const error = new Error(payload.error?.message ?? `HTTP ${response.status}`); error.status = response.status; error.retryAfterMs = Math.max(0, Number(response.headers.get('retry-after') ?? 0) * 1000); throw error; } return payload.data ?? payload;
}
function toast(message, error = false) { const el = $('#toast'); el.textContent = message; el.className = `${error ? 'error ' : ''}show`; clearTimeout(toast.timer); toast.timer = setTimeout(() => { el.className = ''; }, 3500); }
function escapeHtml(value) { return String(value ?? '').replace(/[&<>"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[char]); }
function position(bot) { const p = bot.runtime?.position; return p ? `${p.x.toFixed(1)}, ${p.y.toFixed(1)}, ${p.z.toFixed(1)}` : '—'; }
function online(bot) { return ['READY', 'ACTIVE', 'PAUSED'].includes(bot.status); }

async function refresh() {
  if (state.polling.running || document.hidden) return; state.polling.running = true;
  try {
    const snapshot = await api('/api/v1/dashboard/snapshot'); Object.assign(state, snapshot); render();
    state.polling.failures = 0; $('#connectionDot').style.background = '#77e39e'; $('#connectionText').textContent = 'Connected'; $('#lastUpdate').textContent = new Date().toLocaleTimeString();
  } catch (error) { state.polling.failures++; state.polling.retryAfterMs = error.retryAfterMs; $('#connectionDot').style.background = '#ff7474'; $('#connectionText').textContent = error.status === 429 ? 'Rate limited' : 'Disconnected'; $('#lastUpdate').textContent = error.message; }
  finally { state.polling.running = false; scheduleRefresh(); }
}
function scheduleRefresh() { clearTimeout(state.polling.timer); if (document.hidden) return; const backoff = Math.min(30_000, 3000 * (2 ** state.polling.failures)); const delay = Math.max(3000, state.polling.retryAfterMs ?? 0, backoff); state.polling.retryAfterMs = 0; state.polling.timer = setTimeout(refresh, delay); }
function render() {
  $('#statOnline').textContent = state.bots.filter(online).length; $('#statBots').textContent = state.bots.length;
  $('#statGoals').textContent = state.goals.filter(goal => goal.status === 'ACTIVE').length; $('#statHealth').textContent = state.health?.status ?? '—';
  $('#statAi').textContent = state.ai?.llm?.enabled ? state.ai.llm.provider : 'RULES'; $('#statAiModel').textContent = state.ai?.llm?.model ? `${state.ai.llm.model}${state.ai.llm.keyCount ? ` · key ${state.ai.llm.activeKey} · ready ${state.ai.llm.availableKeys}/${state.ai.llm.keyCount}` : ''}` : 'Deterministic fallback';
  const memory = state.health?.checks?.memory; $('#statMemory').textContent = memory?.count ?? 0; $('#statMemoryDetail').textContent = memory ? `Short ${memory.byType?.SHORT_TERM ?? 0} · Long ${memory.byType?.LONG_TERM ?? 0}` : 'Short 0 · Long 0'; $('#statHive').textContent = state.health?.checks?.hivemind?.activeMembers ?? 0; $('#statMl').textContent = state.health?.checks?.ml?.outcomeCount ?? 0; $('#statProcess').textContent = state.diagnostics ? `${state.diagnostics.rssMb} MB` : '—'; $('#statProcessHeap').textContent = state.diagnostics ? `Heap ${state.diagnostics.heapUsedMb} MB · uptime ${state.diagnostics.uptimeSeconds}s` : 'Runtime diagnostics';
  $('#statLogistics').textContent = state.logistics?.activeStorages ?? 0; $('#statLogisticsDetail').textContent = state.logistics ? `${state.logistics.stockItems} items · ${state.logistics.activeReservations} reserved` : 'Storage backbone';
  $('#statQueue').textContent = state.taskQueue?.queuedTasks ?? 0; $('#statQueueDetail').textContent = state.taskQueue ? `${state.taskQueue.activeBots} bots running · ${state.ai?.queuedOperations ?? 0} coordinator waiting` : 'Sequential per bot';
  $('#overviewBots').innerHTML = state.bots.length ? state.bots.map(botRow).join('') : empty('No bots registered');
  $('#goalList').innerHTML = state.goals.length ? state.goals.slice(-6).reverse().map(goal => `<div class="goal-row"><div><b>${escapeHtml(goal.description)}</b><small>${goal.progress}% · ${new Date(goal.updatedAt).toLocaleTimeString()}</small></div><span class="badge">${goal.status}</span></div>`).join('') : empty('No goals yet');
  $('#botManager').innerHTML = state.bots.length ? state.bots.map(botCard).join('') : empty('Add your first bot using the form');
  const classes = [...new Set(state.bots.map(bot => bot.metadata?.className).filter(Boolean))];
  replaceOptions($('#commandBot'), `<option value="scope:global">All bots · !global</option>${classes.map(name => `<option value="class:${escapeHtml(name)}">Class ${escapeHtml(name)} · !${escapeHtml(name)}</option>`).join('')}${state.bots.map(bot => `<option value="bot:${escapeHtml(bot.id)}">${escapeHtml(bot.name)} · !${escapeHtml(bot.metadata?.commandAlias ?? bot.name)} · ${bot.status}</option>`).join('')}`);
  $('#adminList').innerHTML = state.admins.length ? state.admins.map(admin => `<div class="admin-row"><div><b>${escapeHtml(admin.username)}</b><div class="source">${admin.source}</div></div>${admin.removable ? `<button class="button danger" data-remove-admin="${escapeHtml(admin.username)}">Remove</button>` : '<span class="badge">.env</span>'}</div>`).join('') : empty('No chat admins configured');
  renderSettings(); renderOpenBotInventory();
  renderCameras(); bindDynamic();
}
function renderSettings() {
  if (!state.settings) return; const llm = state.settings.llm; const autonomy = state.settings.autonomy; const acquisition = state.settings.acquisition ?? {};
  hydrateFormOnce($('#llmSettingsForm'), () => { $('#llmProvider').value = llm.provider ?? 'none'; $('#openRouterModel').value = llm.openrouter.model; $('#openRouterEndpoint').value = llm.openrouter.endpoint; $('#nvidiaNimModel').value = llm.nvidia.model; $('#nvidiaNimEndpoint').value = llm.nvidia.endpoint; });
  $('#llmSettingStatus').textContent = llm.status?.enabled ? `${llm.status.provider} · ${llm.status.model}` : 'disabled'; const keySummary = provider => provider.configuredKeys.map((configured, index) => `#${index + 1} ${configured ? 'configured' : 'empty'}`).join(' · '); $('#keyStatus').textContent = `OpenRouter: ${keySummary(llm.openrouter)}. NVIDIA: ${keySummary(llm.nvidia)}. Mengisi key baru hanya mengganti pool provider tersebut.`;
  hydrateCleanForm($('#logSettingsForm'), () => { $('#logLevel').value = state.settings.log.level; }); hydrateCleanForm($('#autonomySettingsForm'), () => { $('#autonomyEnabled').checked = autonomy.status === 'ACTIVE'; $('#autonomyInterval').value = autonomy.intervalMs; $('#autonomyBudget').value = autonomy.maxActionsPerHour; }); $('#autonomySettingStatus').textContent = autonomy.status;
  hydrateCleanForm($('#acquisitionSettingsForm'), () => {
    $('#acquisitionEnabled').checked = Boolean(acquisition.enabled);
    $('#acquisitionMaxDepth').value = acquisition.maxDepth ?? 8;
    $('#acquisitionMaxSubtasks').value = acquisition.maxSubtasks ?? 32;
    $('#acquisitionMaxAttempts').value = acquisition.maxAttempts ?? 3;
    $('#acquisitionMaxDistance').value = acquisition.maxDistance ?? 2000;
    $('#acquisitionStorageFirst').checked = Boolean(acquisition.storageFirst);
    $('#acquisitionAllowFleet').checked = Boolean(acquisition.allowFleet);
    $('#acquisitionAllowCraft').checked = Boolean(acquisition.allowCraft);
    $('#acquisitionAllowSmelt').checked = Boolean(acquisition.allowSmelt);
    $('#acquisitionAllowCollect').checked = Boolean(acquisition.allowCollect);
    $('#acquisitionAllowPartial').checked = Boolean(acquisition.allowPartial);
    $('#acquisitionToolPreservation').checked = Boolean(acquisition.toolPreservation);
  });
  $('#acquisitionSettingStatus').textContent = acquisition.enabled ? 'ENABLED' : 'DISABLED';
  $('#autonomyObjectives').innerHTML = state.autonomyObjectives.length ? state.autonomyObjectives.map(objective => `<div class="goal-row"><div><b>${escapeHtml(objective.text)}</b><small>${escapeHtml(objective.selector)} · runs ${objective.runs} · success ${objective.successes} · failed ${objective.failures}</small></div><button class="button danger" data-remove-objective="${escapeHtml(objective.id)}">Remove</button></div>`).join('') : empty('No autonomous objectives');
}
function replaceOptions(select, html) { const selected = select.value; select.innerHTML = html; if ([...select.options].some(option => option.value === selected)) select.value = selected; }
function hydrateCleanForm(form, operation) { if (form.dataset.dirty !== 'true') operation(); }
function hydrateFormOnce(form, operation) { if (form.dataset.hydrated === 'true') return; const hasDraft = form.dataset.dirty === 'true' || [...form.querySelectorAll('input[type="password"]')].some(input => input.value); if (!hasDraft) operation(); form.dataset.hydrated = 'true'; form.dataset.dirty = hasDraft ? 'true' : 'false'; }
function trackDirty(form) { const dirty = () => { form.dataset.dirty = 'true'; }; form.addEventListener('input', dirty); form.addEventListener('change', dirty); }
function markClean(form) { form.dataset.dirty = 'false'; }
function resetHydration(form) { form.dataset.hydrated = 'false'; form.dataset.dirty = 'false'; }
function botRow(bot) { return `<div class="bot-row"><div class="bot-main"><i class="status-dot ${bot.status.toLowerCase()}"></i><div><b>${escapeHtml(bot.name)}</b><small>${bot.status} · ${position(bot)}</small></div></div><span class="badge">HP ${bot.runtime?.health ?? '—'}</span></div>`; }
function botCard(bot) { const ready = online(bot); const activeCamera = bot.runtime?.camera?.active; const inventory = bot.runtime?.inventorySummary ?? []; const preview = inventory.length ? inventory.slice(0, 4).map(item => `${escapeHtml(item.name)}:${item.count}`).join(' · ') : 'Inventory empty'; const cameraButtons = activeCamera ? `<button class="button secondary" data-camera="stop" data-bot="${bot.id}">Stop viewer</button>` : `<button class="button secondary" data-camera="start" data-camera-mode="first_person" data-bot="${bot.id}" ${ready ? '' : 'disabled'}>First person</button><button class="button secondary" data-camera="start" data-camera-mode="surrounding" data-bot="${bot.id}" ${ready ? '' : 'disabled'}>3D area</button>`; return `<article class="bot-card"><div class="bot-card-head"><div><h3>${escapeHtml(bot.name)}</h3><small>!${escapeHtml(bot.metadata?.commandAlias ?? bot.name)} · class !${escapeHtml(bot.metadata?.className ?? 'worker')}</small></div><i class="status-dot ${bot.status.toLowerCase()}"></i></div><dl><div><dt>Status</dt><dd>${bot.status}</dd></div><div><dt>Health / food</dt><dd>${bot.runtime?.health ?? '—'} / ${bot.runtime?.food ?? '—'}</dd></div><div><dt>Position</dt><dd>${position(bot)}</dd></div><div><dt>Dimension</dt><dd>${bot.runtime?.dimension ?? '—'}</dd></div></dl><div class="inventory-preview"><b>Inventory:</b> ${preview}${inventory.length > 4 ? ` · +${inventory.length - 4} stacks` : ''}</div><div class="actions"><button class="button primary" data-bot-action="${ready ? 'stop' : 'start'}" data-bot="${bot.id}">${ready ? 'Disconnect' : 'Join server'}</button>${cameraButtons}<button class="button secondary" data-edit-bot="${bot.id}">Edit & inventory</button><button class="button danger" data-delete-bot="${bot.id}">Delete</button></div></article>`; }
function renderCameras() {
  const wall = $('#cameraWall'); const active = state.bots.filter(bot => bot.runtime?.camera?.active && bot.runtime.camera.port); const ids = new Set(active.map(bot => bot.id));
  wall.querySelectorAll('[data-camera-card]').forEach(card => { if (!ids.has(card.dataset.cameraCard)) card.remove(); }); wall.querySelector('.camera-empty')?.remove();
  for (const bot of active) {
    if (wall.querySelector(`[data-camera-card="${CSS.escape(bot.id)}"]`)) continue;
    const card = document.createElement('article'); card.className = 'camera-card'; card.dataset.cameraCard = bot.id;
    const mode = bot.runtime.camera.mode === 'surrounding' ? '3D AREA' : 'FIRST PERSON'; const warning = bot.runtime.camera.versionSupported === false ? `<span class="camera-warning">${escapeHtml(bot.runtime.camera.version)} → renderer ${escapeHtml(bot.runtime.camera.renderVersion)}</span>` : `<span class="camera-live">${mode}</span>`;
    card.innerHTML = `<header><div><b>◉ ${escapeHtml(bot.name)}</b>${warning}</div><button class="button danger" data-camera="stop" data-bot="${escapeHtml(bot.id)}">Stop</button></header><div class="camera-loading">Connecting to camera…</div><iframe loading="eager" title="Camera ${escapeHtml(bot.name)}" src="http://${location.hostname}:${bot.runtime.camera.port}"></iframe>`;
    const frame = card.querySelector('iframe'); frame.onload = () => card.querySelector('.camera-loading')?.remove(); wall.append(card);
  }
  if (!active.length && !wall.querySelector('.camera-empty')) wall.innerHTML = '<div class="camera-empty">Start a camera from the Bots menu to show it here.</div>';
}
function empty(text) { return `<div class="camera-empty" style="padding:28px">${text}</div>`; }

function bindDynamic() {
  $$('[data-bot-action]').forEach(button => button.onclick = () => performBot(button.dataset.bot, button.dataset.botAction));
  $$('[data-camera]').forEach(button => button.onclick = () => camera(button.dataset.bot, button.dataset.camera, button.dataset.cameraMode));
  $$('[data-delete-bot]').forEach(button => button.onclick = () => deleteBot(button.dataset.deleteBot));
  $$('[data-edit-bot]').forEach(button => button.onclick = () => editBot(button.dataset.editBot));
  $$('[data-remove-admin]').forEach(button => button.onclick = () => removeAdmin(button.dataset.removeAdmin));
  $$('[data-remove-objective]').forEach(button => button.onclick = () => removeObjective(button.dataset.removeObjective));
}
async function performBot(id, action) { try { await api(`/api/v1/bots/${id}/${action}`, { method: 'POST' }); toast(action === 'start' ? 'Bot is joining the server' : 'Bot disconnected'); await refresh(); } catch (error) { toast(error.message, true); } }
async function camera(id, action, mode) { try { await api(`/api/v1/bots/${id}/camera/${action}`, { method: 'POST', body: JSON.stringify(mode ? { mode } : {}) }); toast(action === 'start' ? `${mode === 'surrounding' ? '3D area' : 'First-person viewer'} started` : 'Viewer stopped'); await refresh(); if (action === 'start') showView('cameras'); } catch (error) { toast(error.message, true); } }
async function deleteBot(id) { if (!confirm('Disconnect and permanently remove this bot profile?')) return; try { await api(`/api/v1/bots/${id}`, { method: 'DELETE' }); toast('Bot removed'); await refresh(); } catch (error) { toast(error.message, true); } }
function editBot(id) { const bot = state.bots.find(item => item.id === id); if (!bot) return; const profile = bot.profile ?? {}; state.editorBotId = id; $('#editBotId').value = bot.id; $('#editBotName').value = profile.name ?? bot.name; $('#editBotUsername').value = profile.username ?? bot.name; $('#editBotHost').value = profile.host ?? 'localhost'; $('#editBotPort').value = profile.port ?? 25565; $('#editBotAuth').value = profile.auth ?? 'offline'; $('#editBotVersion').value = profile.version ?? ''; $('#editBotAlias').value = bot.metadata?.commandAlias ?? bot.name; $('#editBotClass').value = bot.metadata?.className ?? 'worker'; $('#editBotAutoConnect').checked = Boolean(profile.autoConnect); renderBotInventory(bot); $('#botEditor').showModal(); }
function renderOpenBotInventory() { if (!state.editorBotId || !$('#botEditor').open) return; const bot = state.bots.find(item => item.id === state.editorBotId); if (bot) renderBotInventory(bot); }
function renderBotInventory(bot) { const inventory = bot.runtime?.inventorySummary ?? []; $('#editBotTitle').textContent = `${bot.name} · ${bot.status}`; $('#editBotInventory').innerHTML = inventory.length ? inventory.map(item => `<div class="inventory-item"><span>${escapeHtml(item.name)}</span><b>${item.count}</b></div>`).join('') : empty('Inventory empty or bot offline'); $('#editBotInventoryUpdated').textContent = `Live · ${new Date(bot.runtime?.timestamp ?? Date.now()).toLocaleTimeString()}`; $('#editBotHint').textContent = online(bot) ? 'Nama tampilan, alias, kelompok, dan auto-connect dapat diubah sekarang. Disconnect bot sebelum mengganti username, server, authentication, atau protocol.' : 'Semua konfigurasi dapat diedit saat bot offline.'; }
async function removeAdmin(username) { try { await api(`/api/v1/admins/${encodeURIComponent(username)}`, { method: 'DELETE' }); toast('Admin removed'); await refresh(); } catch (error) { toast(error.message, true); } }
async function removeObjective(id) { try { await api(`/api/v1/autonomy/objectives/${encodeURIComponent(id)}`, { method: 'DELETE' }); toast('Autonomy objective removed'); await refresh(); } catch (error) { toast(error.message, true); } }

