$('#botEditorForm').onsubmit = async event => { event.preventDefault(); const id = $('#editBotId').value; const input = { name: $('#editBotName').value.trim(), username: $('#editBotUsername').value.trim(), host: $('#editBotHost').value.trim(), port: Number($('#editBotPort').value), auth: $('#editBotAuth').value, version: $('#editBotVersion').value.trim() || null, commandAlias: $('#editBotAlias').value.trim(), className: $('#editBotClass').value.trim(), autoConnect: $('#editBotAutoConnect').checked }; try { await api(`/api/v1/bots/${id}`, { method: 'PATCH', body: JSON.stringify(input) }); $('#botEditor').close(); toast('Bot configuration saved'); await refresh(); } catch (error) { toast(error.message, true); } };
$('#adminForm').onsubmit = async event => { event.preventDefault(); const username = new FormData(event.target).get('username'); try { await api('/api/v1/admins', { method: 'POST', body: JSON.stringify({ username }) }); event.target.reset(); toast('Admin added'); await refresh(); } catch (error) { toast(error.message, true); } };
$('#llmSettingsForm').onsubmit = async event => { event.preventDefault(); const openRouterApiKeys = [$('#openRouterKey1').value.trim(), $('#openRouterKey2').value.trim(), $('#openRouterKey3').value.trim()].filter(Boolean); const nvidiaApiKeys = [$('#nvidiaKey1').value.trim(), $('#nvidiaKey2').value.trim(), $('#nvidiaKey3').value.trim()].filter(Boolean); const input = { provider: $('#llmProvider').value, openRouterModel: $('#openRouterModel').value.trim(), openRouterEndpoint: $('#openRouterEndpoint').value.trim(), nvidiaModel: $('#nvidiaNimModel').value.trim(), nvidiaEndpoint: $('#nvidiaNimEndpoint').value.trim(), ...(openRouterApiKeys.length ? { openRouterApiKeys } : {}), ...(nvidiaApiKeys.length ? { nvidiaApiKeys } : {}) }; try { await api('/api/v1/settings/llm', { method: 'PATCH', body: JSON.stringify(input) }); for (const id of ['#openRouterKey1', '#openRouterKey2', '#openRouterKey3', '#nvidiaKey1', '#nvidiaKey2', '#nvidiaKey3']) $(id).value = ''; markClean(event.target); toast('LLM runtime settings applied'); await refresh(); } catch (error) { toast(error.message, true); } };
$('#autonomySettingsForm').onsubmit = async event => { event.preventDefault(); const input = { enabled: $('#autonomyEnabled').checked, intervalMs: Number($('#autonomyInterval').value), maxActionsPerHour: Number($('#autonomyBudget').value) }; try { await api('/api/v1/settings/autonomy', { method: 'PATCH', body: JSON.stringify(input) }); markClean(event.target); toast('Autonomy settings applied'); await refresh(); } catch (error) { toast(error.message, true); } };
$('#autonomyObjectiveForm').onsubmit = async event => { event.preventDefault(); const input = { text: $('#autonomyObjective').value.trim(), selector: $('#autonomySelector').value.trim() }; try { await api('/api/v1/autonomy/objectives', { method: 'POST', body: JSON.stringify(input) }); $('#autonomyObjective').value = ''; toast('Autonomy objective added'); await refresh(); } catch (error) { toast(error.message, true); } };
$('#logSettingsForm').onsubmit = async event => { event.preventDefault(); try { await api('/api/v1/settings/log', { method: 'PATCH', body: JSON.stringify({ level: $('#logLevel').value }) }); markClean(event.target); toast('Runtime log level applied'); await refresh(); await loadRuntimeLogs(); } catch (error) { toast(error.message, true); } };
$('#acquisitionSettingsForm').onsubmit = async event => { event.preventDefault(); const input = { enabled: $('#acquisitionEnabled').checked, maxDepth: Number($('#acquisitionMaxDepth').value), maxSubtasks: Number($('#acquisitionMaxSubtasks').value), maxAttempts: Number($('#acquisitionMaxAttempts').value), maxDistance: Number($('#acquisitionMaxDistance').value), storageFirst: $('#acquisitionStorageFirst').checked, allowFleet: $('#acquisitionAllowFleet').checked, allowCraft: $('#acquisitionAllowCraft').checked, allowSmelt: $('#acquisitionAllowSmelt').checked, allowCollect: $('#acquisitionAllowCollect').checked, allowPartial: $('#acquisitionAllowPartial').checked, toolPreservation: $('#acquisitionToolPreservation').checked }; try { await api('/api/v1/settings/acquisition', { method: 'PATCH', body: JSON.stringify(input) }); markClean(event.target); toast('Acquisition settings applied'); await refresh(); } catch (error) { toast(error.message, true); } };
$('#memorySettingsForm').onsubmit = async event => { event.preventDefault(); const input = { maxRecords: Number($('#memoryMaxRecords').value), shortTermMaxRecords: Number($('#memoryShortLimit').value), shortTermTtlMs: Number($('#memoryShortTtl').value), promotionAccesses: Number($('#memoryPromotionAccesses').value), promotionImportance: Number($('#memoryPromotionImportance').value), consolidationIntervalMs: Number($('#memoryConsolidationInterval').value) }; try { await api('/api/v1/settings/memory', { method: 'PATCH', body: JSON.stringify(input) }); markClean(event.target); toast('Memory runtime settings applied'); await loadMemory(); } catch (error) { toast(error.message, true); } };
$('#recoverySettingsForm').onsubmit = async event => { event.preventDefault(); const input = { enabled: $('#recoveryEnabled').checked, maxAttempts: Number($('#recoveryMaxAttempts').value), minScore: Number($('#recoveryMinScore').value), optionalScore: Number($('#recoveryOptionalScore').value), urgentScore: Number($('#recoveryUrgentScore').value), despawnTicks: Number($('#recoveryDespawnTicks').value), safetyMarginTicks: Number($('#recoverySafetyMarginTicks').value), maxDistance: Number($('#recoveryMaxDistance').value), dangerLimit: Number($('#recoveryDangerLimit').value) }; try { await api('/api/v1/settings/recovery', { method: 'PATCH', body: JSON.stringify(input) }); markClean(event.target); toast('Death recovery settings applied'); await loadRecovery(); } catch (error) { toast(error.message, true); } };
$('#commandForm').onsubmit = async event => { event.preventDefault(); await executeCommand($('#commandBot').value, $('#commandInput').value); };
$('#aiForm').onsubmit = async event => { event.preventDefault(); const text = $('#aiInput').value.trim(); if (!text) return; log(`> AI ${$('#commandBot').value}: ${text}`); try { const result = await api('/api/v1/ai/command', { method: 'POST', body: JSON.stringify({ text, selector: selectorForApi($('#commandBot').value) }) }); log(JSON.stringify(result, null, 2)); await refresh(); } catch (error) { log(`AI ERROR: ${error.message}`, true); } };
$$('.quick-commands button').forEach(button => button.onclick = () => { $('#commandInput').value = button.dataset.command; $('#commandInput').focus(); });
async function executeCommand(target, text) {
  const [command, ...args] = text.trim().split(/\s+/); let action = command; let input = {};
  if (['collect', 'craft', 'smelt', 'cook', 'masak', 'lebur', 'survey', 'scan', 'jelajah', 'eksplorasi', 'register_chest', 'daftar_chest', 'store', 'simpan', 'retrieve', 'withdraw', 'ambil_chest', 'stock', 'stok', 'farm', 'farming', 'deforest', 'reforest', 'guard', 'combat', 'meat', 'remember', 'place', 'tebang', 'reboisasi'].includes(command)) { log(`> coordinator ${target}: ${text}`); try { const result = await api('/api/v1/ai/command', { method: 'POST', body: JSON.stringify({ text, selector: selectorForApi(target) }) }); log(JSON.stringify(result, null, 2)); await refresh(); } catch (error) { log(`COORDINATOR ERROR: ${error.message}`, true); } return; }
  if (command === 'status' || command === 'inventory') action = 'observe';
  else if (command === 'goto') { action = 'navigate'; input = { x: Number(args[0]), y: Number(args[1]), z: Number(args[2]) }; }
  else if (command === 'follow') input = { username: args[0] };
  else if (command === 'come') input = { username: args[0] };
  else if (command === 'sethome') { action = 'sethome'; input = { name: args[0] ?? 'home' }; }
  else if (command === 'home') input = { name: args[0] ?? 'home' };
  else if (command === 'chat') input = { message: args.join(' ') };
  else if (command !== 'stop' && command !== 'observe') return log(`Unknown command: ${command}`, true);
  const targets = target === 'scope:global' ? state.bots : target.startsWith('class:') ? state.bots.filter(bot => bot.metadata?.className === target.slice(6)) : state.bots.filter(bot => bot.id === target.slice(4));
  if (!targets.length) return log('No bots match the selected target', true);
  log(`> ${target}: ${text}`); const results = await Promise.allSettled(targets.map(bot => api(`/api/v1/bots/${bot.id}/actions/${action}`, { method: 'POST', body: JSON.stringify(input) })));
  results.forEach((result, index) => log(`${targets[index].name}: ${result.status === 'fulfilled' ? JSON.stringify(result.value) : `ERROR ${result.reason.message}`}`, result.status === 'rejected')); await refresh();
}
